// PA250BattleAudio.h — battle sounds: gunfire, ball whiz, impacts, ramrod, melee, shouted orders.
// Assets live in /Game/PA250/Audio (SFX synthesized by tools/audio/synth_sfx.py; voices generated by
// tools/audio/gen_voice_lines.py, imported by Scripts/import_audio.py). Variants are found by name
// (<bank>_1.._N) so adding a file adds variety without code changes. Missing assets are silent, not errors.
#pragma once

#include "CoreMinimal.h"

class USoundBase;
class USoundAttenuation;

enum class EPA250SoundRange : uint8
{
	Gunfire,  // heard across the field, muffled with distance
	Voice,    // an officer's shout carries ~60 m
	Near,     // ramrod, swing, impact: a few metres
	Whiz      // a ball going past your ear
};

struct PLAYAMERICA250_API FPA250BattleAudio
{
	/** Random variant of a bank, e.g. "musket_fire" -> /Game/PA250/Audio/SFX/musket_fire_3. */
	static USoundBase* Pick(const FString& Bank);
	/** Shouted line for a side, e.g. ("british", "make_ready") -> /Game/PA250/Audio/Voice/british/VO_make_ready. */
	static USoundBase* Voice(FName Faction, const FString& Key);

	/** Play a bank at a location with distance falloff for its range. Returns true if a sound was started. */
	static bool PlayAt(const UObject* Ctx, const FString& Bank, const FVector& Location, EPA250SoundRange Range,
		float Volume = 1.f, float PitchJitter = 0.06f);
	/** A musket shot: near shots crack, far ones (> 60 m from the listener) use the distant boom. Volleys are thinned. */
	static bool PlayMusketShot(const UObject* Ctx, const FVector& Muzzle);
	/** A shouted line (rate-limited per key so a squad doesn't stutter the same order). */
	static bool PlayVoice(const UObject* Ctx, FName Faction, const FString& Key, const FVector& Location);

	/** Non-positional UI sound for the local player (hit / kill confirmation). */
	static bool Play2D(const UObject* Ctx, const FString& Bank, float Volume = 1.f);

	/** Where the local player hears from (camera), if any. */
	static bool GetListener(const UObject* Ctx, FVector& Out);

	/** Test hooks: how many times each bank / voice key was asked to play. */
	static int32 GetPlayCount(const FString& BankOrKey);
	static void ResetPlayCounts();
	static USoundAttenuation* AttenuationFor(EPA250SoundRange Range);
};
